/**
 * @name Remote code execution via subprocess
 * @description Detects user-controlled data flowing into subprocess execution APIs within botocore.
 * @kind path-problem
 * @problem.severity error
 * @id py/botocore-subprocess-rce
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SubprocessRceConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "check_output", "run"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SubprocessRceFlow = TaintTracking::Global<SubprocessRceConfig>;
import SubprocessRceFlow::PathGraph

from SubprocessRceFlow::PathNode source, SubprocessRceFlow::PathNode sink
where SubprocessRceFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches subprocess execution $@.", sink.getNode(), "subprocess call"

/**
 * @name Insecure use of eval/exec
 * @description Detects user-controlled data flowing into eval/exec within botocore.
 * @kind path-problem
 * @problem.severity error
 * @id py/botocore-eval-exec
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module EvalExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::builtin(["eval", "exec"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module EvalExecFlow = TaintTracking::Global<EvalExecConfig>;
import EvalExecFlow::PathGraph

from EvalExecFlow::PathNode source, EvalExecFlow::PathNode sink
where EvalExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches eval/exec $@.", source, "code execution"
